    {
        "id": 798645,
        "page": 1,
        "results": [
            {
                "author": "Manuel São Bento",
                "author_details": {
                    "name": "Manuel São Bento",
                    "username": "msbreviews",
                    "avatar_path": null,
                    "rating": 5.0
                },
                "content": "FULL SPOILER-FREE REVIEW @ movieswetextedabout.com/the-running-man-movie-review-a-lot-of-running-for-an-underwhelming-finish-line/\r\n\r\n\"The Running Man falls short of the potential that Edgar Wright and the source material suggested, though it's an efficient vehicle for the talent and charisma of Glen Powell and presents themes that could and should be incisive.\r\n\r\nIts narrative repetition, unnecessary exposure of its messages, and unsatisfactory ending prevent it from becoming a memorable dystopian thriller. It's competent and perfectly acceptable entertainment, but it lacks the impact and significance it promised.\r\n\r\nWe're left with the echo of an undeniable truth: even in the most rigged and predatory spectacle, the fire of hope and rebellion can't be televised, bought, or silenced.\"\r\n\r\nRating: C+",
                "created_at": "2025-11-11T19:48:12.573Z",
                "id": "691392fc380a6254f1875c69",
                "updated_at": "2025-11-11T19:48:12.628Z",
                "url": "https://www.themoviedb.org/review/691392fc380a6254f1875c69"
            },
            {
                "author": "CinemaSerf",
                "author_details": {
                    "name": "CinemaSerf",
                    "username": "Geronimo1967",
                    "avatar_path": "/yz2HPme8NPLne0mM8tBnZ5ZWJzf.jpg",
                    "rating": 6.0
                },
                "content": "With his young daughter in need of some basic medication that he and his wife cannot afford, “Richards” (Glen Powell) sets off to enrol in the most taxing of television game shows. If he can stay alive for thirty days, he will win a gazillion new dollars and be able to live, with his family, like a king. Of course, he learns fairly quickly that this will never be a fair fight as the show’s boss “Killian” (Josh Brolin) makes quite clear. This is going to be brutal stuff, with the population actively encouraged to report his whereabouts for a cash bonus, so the goons or the “hunters” can come and waste him. Now he isn’t exactly your average ye-ha ninja type. He’s more your decent, gym going, family man - so what chance he can adapt and survive in the face of betrayal and bullets? It starts off quite promisingly, and as usual Powell is fully aware that much of his appeal on screen is down to his willingness to wear (nor not) a skimpy towel, but once we get into the adventure proper this all reminded me too too much of a “Hunger Games” production - complete with remote television cameras and exuberant live television coverage from “Bobby T” (Colman Domingo). There’s a blink and you’ll miss it cameo from William H. Macy which could have been delivered by just about anyone and if you’re especially eagle-eyed you might spot Sandra Dickinson here as she and Michael Cera attempt to provide our runaway with some much needed moral support. “Richards” accrues cash for each kill and for each day he survives, and that also reflects the level-up, video-game, style of these adventures with each getting more lucratively perilous and him becoming more like John Wick as the days go by. The sense of menace? Well that doesn’t really survive an increasingly relentless sequence of predictable CGI-driven pyrotechnics and it just possible that Powell isn’t the best casting here. He’s easy on the eye and charismatic, but he isn’t convincing at any stage as things heat up and neither are Brolin or Domingo who just overact. It could readily lose half an hour without compromising the gist of the original Stephen King story and I just couldn’t help thinking it was released too close to “The Long Walk” which is similar in concept and better in delivery. It’s watchable enough, but I’m not sure I will remember it any more than Arnie’s more static, studio-based, version from 1987.",
                "created_at": "2025-11-13T18:10:20.436Z",
                "id": "69161f0c3137c7daf1876402",
                "updated_at": "2025-11-15T20:11:45.656Z",
                "url": "https://www.themoviedb.org/review/69161f0c3137c7daf1876402"
            },
            {
                "author": "JPV852",
                "author_details": {
                    "name": "",
                    "username": "JPV852",
                    "avatar_path": "/xNLOqXXVJf9m7WngUMLIMFsjKgh.jpg",
                    "rating": 7.0
                },
                "content": "Pretty fun and entertaining remake/re-adaptation that features a fine performance from Glen Powell alongside solid action scenes. Josh Brolin's shear presence made home quite good even if it's a thinly written character and one who doesn't have a ton of screen time. Nothing groundbreaking but still worth checking out. **3.75/5**",
                "created_at": "2025-11-15T04:38:11.317Z",
                "id": "691803b3eba221c4a93a4bf2",
                "updated_at": "2025-11-15T04:38:11.450Z",
                "url": "https://www.themoviedb.org/review/691803b3eba221c4a93a4bf2"
            },
            {
                "author": "MovieGuys",
                "author_details": {
                    "name": "",
                    "username": "MovieGuys",
                    "avatar_path": null,
                    "rating": 4.0
                },
                "content": "There's often a very good reason why they say a film is \"adapted\" from a literary work. \r\n\r\nSuch was the case with the 1988 film, \"Running Man\". Ably adapted from Stephen Kings literary work, it condensed a much longer tale, into a manageable and entertaining package. \r\n\r\nRegrettably, what has been repeatedly touted as an advantage, that is the new film, following the literary work of King more closely, is anything but. This is an overly long, at times thoroughly boring film, that's lacking in both pace and direction. Worse still, its narrative is devoid of depth and wit, leaving  characters who feel more like caricatures. Unsurprisingly too, its woke. Who didn't see that coming?\r\n\r\nThe net result is a film  I personally found so tiresome and dreary, I ended up rewatching the thoroughly satisfying original, to cheer myself up.\r\n\r\nIn summary, overly long, lacking in pace and direction, narratively impoverished, populated by card board cut out caricatures. My advice, if you are new to this tale, watch the 1988 original. Its leagues ahead of this burnt offering.",
                "created_at": "2025-11-19T20:50:23.437Z",
                "id": "691e2d8ff94e7995a26e1906",
                "updated_at": "2025-11-19T20:52:14.370Z",
                "url": "https://www.themoviedb.org/review/691e2d8ff94e7995a26e1906"
            }
        ],
        "total_pages": 1,
        "total_results": 4
    }
